import java.util.Arrays;

public class LongestWord {
    public static void main(String[] args) {
        String sentence = "a child is brushing a woman's hair for her";

        String[] words = sentence.split(" ");
        int maxLength = Arrays.stream(words).map(String::length).max().getAsInt();
        String[] longestWords = Arrays.stream(words)
                .filter(word -> word.length() == maxLength)
