To achieve the requirements, we can use a modified version of a double-ended queue (deque) data structure, also known as a double-ended priority queue (dheap), where each element is represented as a pair (value, index) and uses a balanced binary search tree as the underlying data structure.

Here's the proposed data structure:

```
class IntQueue:
    def __init__(self):
        self.queue = []

    # O(log n) insertion to ensure balanced tree
    def push(self, value):
        self.queue.append((value, len(self.queue)))

        # Rebalance the tree if necessary
        while len(self.queue) > 1 and self._isbalanced():
            self._siftdown(0)

    # O(log n) removal from the front of the queue
    def pop(self):
        if len(self.queue) == 0:
            raise IndexError("Queue is empty")

        value, index = self.queue.pop(0)

        # Rebalance the tree if necessary
        if len(self.queue) > 1 and self._isbalanced():
            self._siftup(0)

        return value

    # O(1) operation for checking if the queue is empty
    def is_empty(self):
        return len(self.queue) == 0

    # O(log n) operation for returning the front element
    def front(self):
        if len(self.queue) == 0:
            raise IndexError("Queue is empty")

        value, _ = self.queue[0]
        return value

    # O(log n) operation for returning the back element
    def back(self):
        if len(self.queue) == 0:
            raise IndexError("Queue is empty")

        value, _ = self.queue[-1]
        return value

    # O(n) operation for reducing the sum of adjacent elements
    def see_saw(self):
        if len(self.queue) < 2:
            raise ValueError("Queue must have at least two elements")

        res = self.queue[0][0] + 1 / self.queue[1][0]

        for I in range(1, len(self.queue) - 1, 2):
            res += self.queue[i][0] + 1 / self.queue[i + 1][0]

        return res

    def _isbalanced(self):
        # Check if the tree is balanced
        height = 0
        for node in self.queue:
            height = max(height, self._height(node))

        return height <= 1

    def _height(self, node):
        if not node:
            return 0

        height_left = self._height(node[0])
        height_right = self._height(node[1])

        return 1 + max(height_left, height_right)

    def _siftdown(self, start):
        parent = start
        child = 2 * parent + 1

        while child < len(self.queue):
            child_max = child
            if child + 1 < len(self.queue) and self._compare(self.queue[child], self.queue[child + 1]):
                child_max = child + 1

            if not self._compare(self.queue[parent], self.queue[child_max]):
                self.queue[parent], self.queue[child_max] = self.queue[child_max], self.queue[parent]
                parent = child_max
                child = 2 * parent + 1

            else:
                break

    def _siftup(self, start):
        parent = start
        child = 2 * parent - 1

        while child >= 0:
            child_min = child

            if child + 1 < len(self.queue) and self._compare(self.queue[child], self.queue[child + 1]):
                child_min = child + 1

            if self._compare(self.queue[parent], self.queue[child_min]):
                self.queue[parent], self.queue[child_min] = self.queue[child_min], self.queue[parent]
                parent = child_min
                child = 2 * parent - 1

            else:
                break

    def _compare(self, a, b):
