/**
 * Enforces updated lifecycle hook to avoid mutating internal component state.
 * This rule looks for methods in the updated hook that mutate component state.
 * Additionally, it checks if those methods call other methods that mutate internal component state.
 *
 * @category vue
 * @param {Object} [options] - Options for the rule
 * @param {boolean} [options.noCallMutators=false] - If true, disallows methods that call other methods that mutate internal component state.
 *
 * @example
 * // With `noCallMutators` option disabled:
 * export default {
 *   updated() {
 *     this.data = this.fetchData();
 *     this.clearCache();
 *   },
 *   methods: {
 *     fetchData() {
 *       // OK
 *     },
 *     clearCache() {
 *       // OK
 *     },
 *     mutateState() {
 *       this.data = 'new data'; // Error: Mutating internal component state
 *     },
 *     callMutator() {
 *       this.mutateState(); // Error: Calling a method that mutates internal component state
 *     },
 *   },
 * }
 *
 * // With `noCallMutators` option enabled:
 * export default {
 *   updated() {
 *     this.data = this.fetchData();
 *     this.clearCache();
 *   },
 *   methods: {
 *     fetchData() {
 *       // OK
 *     },
 *     clearCache() {
 *       // OK
 *     },
 *     mutateState() {
 *       this.data = 'new data'; // Error: Mutating internal component state
 *     },
 *     callMutator() {
 *       this.mutateState(); // Error: Calling a method that mutates internal component state
 *     },
 *     callGoodMethod() {
 *       this.fetchData(); // OK
 *     },
 *   },
 * }
 */

const RULE_NAME = 'vue/no-mutating-internal-state';

module.exports = {
  meta: {
    type: 'problem',
    docs: {
      description: 'Enforces updated lifecycle hook to avoid mutating internal component state.',
      category: 'vue',
      recommended: true,
    },
    fixable: 'code',
    messages: {
      mutation: `Avoid mutating internal component state in updated lifecycle hook.`,
      callMutation: `Avoid calling methods that mutate internal component state in updated lifecycle hook.`,
    },
    schema: [
      {
        type: 'object',
        properties: {
          noCallMutators: { type: 'boolean', default: false },
        },
      },
    ],
  },

  create: function(context) {
    const { noCallMutators = false } = context.options[0] || {};

    const isMethodCall = (node) => node.arguments && node.arguments.length > 0;

    function checkMethod(methodNode, methodName) {
      if (
        methodNode.body.type === 'BlockStatement' &&
        methodNode.body.body.some((statement) => {
          const assignmentPattern = statement.left;
          const bindingIdentifier = assignmentPattern.type === 'Identifier' ? assignmentPattern : assignmentPattern.elements[0];

          return bindingIdentifier.name === context.getScope().id.name;
        })
      ) {
        context.report({
          node: methodNode,
          message: `Avoid mutating internal component state in ${methodName}.`,
        });
      }

      if (isMethodCall(methodNode) && hasMutatingMethodCall(methodNode.arguments[0])) {
        context.report({
          node: methodNode,
          message: `Avoid calling a method that mutates internal component state in ${methodName}.`,
        });
      }
    }

    function hasMutatingMethodCall(callNode) {
      return callNode.callee.name === 'mutateState' || callNode.callee.name === 'callMutator';
    }

    return {
      'LifecycleEmbeddedExpression:exit'(node) {
        if (node.parent.type !== 'Updated') {
          return;
        }

        const updatedMethods = node.arguments[0].properties.filter((propNode) => propNode.type === 'MethodDefinition');

        updatedMethods.forEach((methodNode) => {
          const methodName = methodNode.key.name;

          checkMethod(methodNode.value, methodName);

          if (!noCallMutators) {
            methodNode.value.body.body.forEach((statement) => {
              if (isMethodCall(statement) && hasMutatingMethodCall(statement.arguments[0])) {
                context.report({
                  node: methodNode.value,
                  message: `Avoid calling a method that mutates internal component state in ${methodName}.`,
                });
              }
            });
          }
        });
      },
    };
  },
};
```

