export default {
  meta: {
    type: 'suggestion',
    docs: {
      description: 'Prevent mutating internal component state in updated lifecycle hook',
      category: 'Possible Errors',
    },
    fixable: 'code',
    schema: [],
  },

  create: function (context) {
    const vueOptions = context.options[0] || {};
    const { ignore } = vueOptions;

    return {
      'ExpressionStatement > ObjectExpression > MemberExpression[object.name="updated"] > ObjectMethod[callee.name]': function (node) {
        if (ignore && ignore.includes(node.callee.name)) {
          return;
        }

        if (!isStateChangingMethod(node.callee)) {
          return;
        }

        context.report({
          node,
          message: 'Avoid mutating internal component state in updated lifecycle hook',
          fix(fixer) {
            // Replace the method with an arrow function expression
            const arrowFunction = fixer.replaceText(
              node,
              `(currentValue) => ${node.callee.name}(currentValue, ...arguments)`
            );
            // Add a helper function for the state-changing method
            return fixer.insertTextBefore(arrowFunction, `
              const ${node.callee.name} = function(v, ...args) {
                return ${node.callee.name}Wrapper(v, ...args);
              };

              function ${node.callee.name}Wrapper(v, ...args) {
                ${node.body.body.map((statement) => fixer.replaceText(statement, statement.value))};
              }
            `);
          },
        });
      },
    };
  },
};

function isStateChangingMethod(node) {
  // Check if the function modifies any internal component state (e.g. Data properties, events, refs)
  const stateProperties = Object.keys(context.getScope().bindings).filter((binding) => binding.type === 'var');
  const stateChangingMethods = stateProperties.reduce((acc, prop) => {
    if (prop.includes('$')) {
      return [
        ...acc,
        `_${prop}` + (node.name === 'forceUpdate' ? '' : `(${prop})`),
        `_${prop}.value` + (node.name === 'forceUpdate' ? '' : `(${prop})`),
        `_${prop}.handlers` + (node.name === 'forceUpdate' ? '' : `(${prop})`),
        `_${prop}.emitted` + (node.name === 'forceUpdate' ? '' : `(${prop})`),
      ];
    }
    return acc;
  }, []);

  return stateChangingMethods.some((methodName) => {
    const callbackNode = node.parent.arguments[0];
    if (callbackNode.type === 'Identifier' && callbackNode.name === methodName) {
      return true;
    }
    if (callbackNode.type === 'CallExpression') {
      return callbackNode.callee.name === methodName || callbackNode.arguments.some((arg) => arg.type === 'Identifier' && arg.name === methodName);
    }
    return false;
  });
}
