/**
 * Rule to enforce updated lifecycle hooks not containing methods that mutate internal component state
 * @category vue
 * @implements rule
 */

const PATTERN_METHODS_THAT_MUTATE_STATE = {
  name: 'pascalCase',
  pattern: /^(create|update|destroy)\w+/,
};

module.exports = {
  meta: {
    docs: {
      description: 'Disallows updated lifecycle hooks containing methods that mutate internal component state',
      category: 'vue',
      recommended: true,
    },
    type: 'problem',
    fixes: {
      'vue/no-mutating-props': true,
    },
  },

  create(context) {
    return {
      VueLifecycleHookExpression(node) {
        if (node.parent.type !== 'MemberExpression') {
          return;
        }

        const { property: hookName } = node.parent;
        if (hookName.type !== 'Identifier' || hookName.name !== 'updated') {
          return;
        }

        const methods = getNodePropertyValues(node.argument);
        methods.forEach((method) => {
          if (isMethodThatMutatesState(method)) {
            context.report({
              node,
              message: `Updated lifecycle hook "${hookName.name}" should not include methods that mutate internal component state: "${method.name}".`,
            });
          }
          // Check if method calls other methods that mutate internal component state
          const calls = method.body.body;
          calls.forEach((callNode) => {
            if (callNode.type === 'CallExpression' && isMethodThatMutatesState(callNode.callee)) {
              context.report({
                node: callNode,
                message: `Updated lifecycle hook "${hookName.name}" should not include methods that mutate internal component state, indirectly called by "${method.name}".`,
              });
            }
          });
        });
      },
    };
  },
};

function getNodePropertyValues(node) {
  const properties = [];
  while (node.type === 'ObjectExpression') {
    node.properties.forEach((prop) => {
      if (prop.kind === 'init' && prop.value) {
        properties.push(prop.value);
      }
    });
    node = node.parent;
  }
  return properties;
}

function isMethodThatMutatesState(node) {
  if (node.type !== 'FunctionExpression') {
    return false;
  }

  const { body } = node;
  const mutations = [];

  body.body.forEach((stmt) => {
    if (stmt.type === 'AssignmentExpression' && stmt.left.object && stmt.left.object.name === 'this' && stmt.left.property.type === 'Identifier') {
      mutations.push(stmt.left.property.name);
    }
  });

  return mutations.length > 0;
}
